function Invoke-PatchReject([string]$Name,[string[]]$Vector,[string]$Expected){$scriptPath=$patch;if($Vector.Count -ne 3 -or '-P' -notin $Vector -or $scriptPath -notin $Vector -or -not($Vector|?{$_ -like '-DJE_LUA_WORK:PATH=*'})){throw "$Name argv mode/count guard failed"};$rec=[pscustomobject]@{name=$Name;cwd=(Get-Location).Path;executable='cmake.exe';argv=$Vector;argv_count=$Vector.Count;expected_diagnostic=$Expected};$rec|ConvertTo-Json -Depth 4|Set-Content -LiteralPath (Join-Path $ev "$Name.argv.json") -Encoding utf8;$sw=[Diagnostics.Stopwatch]::StartNew();& cmake.exe @Vector *> (Join-Path $ev "$Name.log");$native=$LASTEXITCODE;$sw.Stop();$found=(Get-Content -LiteralPath (Join-Path $ev "$Name.log") -Raw).Contains($Expected);$res=[pscustomobject]@{name=$Name;exitcode=$native;elapsed_seconds=$sw.Elapsed.TotalSeconds;diagnostic_found=$found;expected_diagnostic=$Expected};$res|ConvertTo-Json -Depth 4|Set-Content -LiteralPath (Join-Path $ev "$Name.result.json") -Encoding utf8;$native|Set-Content -LiteralPath (Join-Path $ev "$Name.exitcode") -NoNewline;$sw.Elapsed.TotalSeconds.ToString('F6',[Globalization.CultureInfo]::InvariantCulture)|Set-Content -LiteralPath (Join-Path $ev "$Name.elapsed.txt") -NoNewline;return $res}
