foreach($mode in @('missing','ambiguous')){$work=Join-Path $fixtures $mode;$load=$original;if($mode -eq 'missing'){$load=$load.Replace($old,$old.Replace('static void pusherror','static void je_pusherror_removed'));$expected='original patch hunk missing: loadlib Windows error';if($load.Contains($old)){throw 'Missing fixture still contains hunk'}}else{$load=$load.Replace($old,$old+"`n"+$old);$expected='ambiguous patch hunk: loadlib Windows error';if(([regex]::Matches($load,[regex]::Escape($old))).Count -ne 2){throw 'Ambiguous fixture lacks duplicate hunk'}};[IO.File]::WriteAllText((Join-Path $work 'loadlib.c'),$load);[IO.File]::WriteAllText((Join-Path $work 'loslib.c'),$losOriginal);$loadBefore=(Get-FileHash -LiteralPath (Join-Path $work 'loadlib.c') -Algorithm SHA256).Hash;$losBefore=(Get-FileHash -LiteralPath (Join-Path $work 'loslib.c') -Algorithm SHA256).Hash;$argv=[string[]]@("-DJE_LUA_WORK:PATH=$work",'-P',$patch);$r=Invoke-PatchReject "patch-$mode" $argv $expected;$loadAfter=(Get-FileHash -LiteralPath (Join-Path $work 'loadlib.c') -Algorithm SHA256).Hash;$losAfter=(Get-FileHash -LiteralPath (Join-Path $work 'loslib.c') -Algorithm SHA256).Hash;$unchanged=($loadBefore -eq $loadAfter -and $losBefore -eq $losAfter);$r|Add-Member -NotePropertyName loadlib_sha_before -NotePropertyValue $loadBefore;$r|Add-Member -NotePropertyName loadlib_sha_after -NotePropertyValue $loadAfter;$r|Add-Member -NotePropertyName loslib_sha_before -NotePropertyValue $losBefore;$r|Add-Member -NotePropertyName loslib_sha_after -NotePropertyValue $losAfter;$r|Add-Member -NotePropertyName both_work_files_unchanged -NotePropertyValue $unchanged;if($r.exitcode -eq 0 -or -not $r.diagnostic_found -or -not $unchanged){throw "$mode exact-hunk rejection/atomicity failed"};$r|ConvertTo-Json -Depth 4|Set-Content -LiteralPath (Join-Path $ev "patch-$mode.result.json") -Encoding utf8;$results+=,$r}
